import { describe, expect, it } from 'vitest';
import { CodecError, encodeBytesLocal, parseShift, runLocal, runsInBrowser } from './codecs';
import parity from './parity.json';

const ONE_WAY = new Set(['sha1', 'sha256', 'sha512']);

// parity.json is generated by backend/parity.py from the Python implementation.
describe('browser codecs match the Python backend', () => {
  it.each(parity.map(c => [c.alg, JSON.stringify(c.text), c]))('%s encodes %s identically', async (_alg, _t, c) => {
    expect(runsInBrowser(c.alg)).toBe(true);
    expect(await runLocal(c.alg, 'encode', c.text, c.key)).toBe(c.encoded);
  });

  // Morse has no codes for many characters (they encode as "?"), so only
  // representable Morse samples can round-trip.
  const reversible = parity.filter(c => !ONE_WAY.has(c.alg) && !(c.alg === 'morse' && c.encoded.includes('?')));
  it.each(reversible.map(c => [c.alg, JSON.stringify(c.text), c]))(
    '%s decodes %s back to the original',
    async (_alg, _t, c) => {
      const expected = c.alg === 'morse' ? c.text.trim().split(/\s+/).filter(Boolean).join(' ') : c.text;
      expect(await runLocal(c.alg, 'decode', c.encoded, c.key)).toBe(expected);
    },
  );
});

describe('error handling', () => {
  it.each([
    ['base64', 'not base64!!'],
    ['hex', 'abc'],
    ['hex', 'zz'],
    ['binary', '102'],
    ['binary', '111111111'],
    ['octal', '400'],
    ['unicode', 'hello'],
    ['decimal', 'abc'],
    ['url', '%E0%A4%A'],
  ])('%s rejects %j with a CodecError', async (alg, input) => {
    await expect(runLocal(alg, 'decode', input, '')).rejects.toBeInstanceOf(CodecError);
  });

  it('rejects invalid UTF-8 bytes', async () => {
    await expect(runLocal('hex', 'decode', 'ff', '')).rejects.toThrow(/UTF-8/);
  });

  it('requires a letter in the Vigenère key', async () => {
    await expect(runLocal('vigenere', 'encode', 'hi', '123')).rejects.toThrow(/at least one letter/);
  });

  it('refuses to decode a hash', async () => {
    await expect(runLocal('sha256', 'decode', 'abc', '')).rejects.toThrow(/one-way/);
  });
});

describe('details', () => {
  it('parses Caesar shifts like the backend', () => {
    expect(parseShift('3')).toBe(3);
    expect(parseShift('-1')).toBe(25);
    expect(parseShift(' 29 ')).toBe(3);
    expect(parseShift('abc')).toBe(3);
    expect(parseShift('')).toBe(3);
  });

  it('accepts whitespace inside Base64 and hex input', async () => {
    expect(await runLocal('base64', 'decode', 'SGVs\nbG8=', '')).toBe('Hello');
    expect(await runLocal('hex', 'decode', '48 65 6c\n6c 6f', '')).toBe('Hello');
  });

  it('returns null for algorithms that need the backend', async () => {
    expect(runsInBrowser('aes')).toBe(false);
    expect(await runLocal('aes', 'encode', 'x', 'k')).toBeNull();
    expect(await encodeBytesLocal('sha3_256', new Uint8Array([1]))).toBeNull();
  });

  it('hashes and encodes file bytes', async () => {
    const bytes = new TextEncoder().encode('hello');
    expect(await encodeBytesLocal('base64', bytes)).toBe('aGVsbG8=');
    expect(await encodeBytesLocal('sha256', bytes)).toBe('2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824');
  });

  it('base64-encodes large inputs without overflowing the stack', async () => {
    const bytes = new Uint8Array(3_000_000).fill(65);
    const out = await encodeBytesLocal('base64', bytes);
    expect(out.length).toBe(4_000_000);
  });
});
